use stdpython :: * ; pub fn python_main () -> Result < () , PyException > { print (& ("Python main function")) ; Ok (()) } pub fn another_function () -> Result < () , PyException > { print (& ("Another function")) ; Ok (()) } fn main () { let __rython_result = (|| -> Result < () , PyException > { python_main () ? ; print (& ("First main block")) ; another_function () ? ; print (& ("Second main block")) ; Ok (()) }) () ; if let Err (e) = __rython_result { eprintln ! ("{}" , e) ; std :: process :: exit (1) ; } }